1	/**
2	 * Rule-based comment redaction (ADR 0001, ADR 0009).
3	 * Runs at store time in the Submission Worker so that no raw comment is ever kept at rest.
4	 */
5	
6	export type RosterItem =
7	  | string
8	  | {
9	      readonly name?: string | null | undefined;
10	      readonly firstName?: string | null | undefined;
11	      readonly lastName?: string | null | undefined;
12	      readonly email?: string | null | undefined;
13	    };
14	
15	export type Roster = ReadonlyArray<RosterItem>;
16	
17	const URL_PATTERN = /(?:https?:\/\/|www\.)[^\s<>"'()[\]{},]+(?<![.,!?:;])/gi;
18	const EMAIL_PATTERN = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/gi;
19	const HANDLE_PATTERN = /(?:^|(?<=[^\w@]))@[A-Za-z0-9_]+(?=[^\w]|$)/g;
20	
21	// 7+ digits with common separators (+, -, ., space, parentheses, slash)
22	const PHONE_PATTERN =
23	  /(?:^|(?<=[^\w+]))((?:\+\d{1,4}[-.\s]?)?(?:\(?\d{2,5}\)?[-.\s]?)(?:\d{2,5}[-.\s]?){1,4}\d{2,5})(?=[^\w]|$)/g;
24	
25	const stripDiacritics = (text: string): string =>
26	  text
27	    .normalize("NFKD")
28	    .replace(/[\u0300-\u036f]/g, "")
29	    .toLowerCase();
30	
31	interface CandidateName {
32	  readonly norm: string;
33	  readonly words: ReadonlyArray<string>;
34	  readonly wordCount: number;
35	}
36	
37	const extractCandidateNames = (roster: Roster): ReadonlyArray<CandidateName> => {
38	  const rawNames = new Set<string>();
39	
40	  for (const item of roster) {
41	    if (typeof item === "string") {
42	      const trimmed = item.trim();
43	      if (trimmed.includes("@")) {
44	        const localPart = trimmed.split("@")[0] ?? "";
45	        if (localPart) {
46	          rawNames.add(localPart);
47	          for (const sub of localPart.split(/[._-]/)) {
48	            if (sub) rawNames.add(sub);
49	          }
50	        }
51	      } else {
52	        rawNames.add(trimmed);
53	        for (const sub of trimmed.split(/\s+/)) {
54	          if (sub) rawNames.add(sub);
55	        }
56	      }
57	    } else if (item && typeof item === "object") {
58	      if (item.name) {
59	        rawNames.add(item.name.trim());
60	        for (const sub of item.name.trim().split(/\s+/)) {
61	          if (sub) rawNames.add(sub);
62	        }
63	      }
64	      if (item.firstName) rawNames.add(item.firstName.trim());
65	      if (item.lastName) rawNames.add(item.lastName.trim());
66	      if (item.email) {
67	        const localPart = item.email.trim().split("@")[0] ?? "";
68	        if (localPart) {
69	          rawNames.add(localPart);
70	          for (const sub of localPart.split(/[._-]/)) {
71	            if (sub) rawNames.add(sub);
72	          }
73	        }
74	      }
75	    }
76	  }
77	
78	  const seen = new Set<string>();
79	  const candidates: Array<CandidateName> = [];
80	
81	  for (const name of rawNames) {
82	    const norm = stripDiacritics(name.trim());
83	    if (norm.length < 2 || seen.has(norm)) continue;
84	    seen.add(norm);
85	
86	    const words = norm.split(/\s+/).filter((w) => w.length > 0);
87	    if (words.length > 0) {
88	      candidates.push({
89	        norm,
90	        words,
91	        wordCount: words.length,
92	      });
93	    }
94	  }
95	
96	  // Greedy match: multi-word names first, then longer names
97	  return candidates.sort((a, b) => b.wordCount - a.wordCount || b.norm.length - a.norm.length);
98	};
