100	const redactNames = (text: string, candidates: ReadonlyArray<CandidateName>): string => {
101	  if (candidates.length === 0) return text;
102	
103	  const segmenter = new Intl.Segmenter("en", { granularity: "word" });
104	  const segments = [...segmenter.segment(text)];
105	
106	  let result = "";
107	  let i = 0;
108	
109	  while (i < segments.length) {
110	    const seg = segments[i];
111	    if (seg === undefined) break;
112	
113	    if (!seg.isWordLike) {
114	      result += seg.segment;
115	      i++;
116	      continue;
117	    }
118	
119	    let matched = false;
120	
121	    for (const candidate of candidates) {
122	      if (candidate.wordCount > 1) {
123	        // Multi-word name lookahead
124	        let wordIdx = i;
125	        let matchedCount = 0;
126	        let spanEnd = i;
127	        const collectedWords: Array<string> = [];
128	        let possessiveSuffix = "";
129	
130	        while (wordIdx < segments.length && matchedCount < candidate.wordCount) {
131	          const nextSeg = segments[wordIdx];
132	          if (nextSeg === undefined) break;
133	          if (nextSeg.isWordLike) {
134	            let segWord = nextSeg.segment;
135	            if (matchedCount === candidate.wordCount - 1) {
136	              if (segWord.endsWith("'s") || segWord.endsWith("’s")) {
137	                possessiveSuffix = segWord.slice(-2);
138	                segWord = segWord.slice(0, -2);
139	              }
140	            }
141	            collectedWords.push(stripDiacritics(segWord));
142	            matchedCount++;
143	            spanEnd = wordIdx;
144	          }
145	          wordIdx++;
146	        }
147	
148	        if (matchedCount === candidate.wordCount && collectedWords.join(" ") === candidate.words.join(" ")) {
149	          result += "[name]" + possessiveSuffix;
150	          i = spanEnd + 1;
151	          matched = true;
152	          break;
153	        }
154	      } else {
155	        // Single word candidate
156	        let word = seg.segment;
157	        let suffix = "";
158	        if (word.endsWith("'s") || word.endsWith("’s")) {
159	          suffix = word.slice(-2);
160	          word = word.slice(0, -2);
161	        }
162	
163	        if (stripDiacritics(word) === candidate.norm) {
164	          result += "[name]" + suffix;
165	          i++;
166	          matched = true;
167	          break;
168	        }
169	      }
170	    }
171	
172	    if (!matched) {
173	      result += seg.segment;
174	      i++;
175	    }
176	  }
177	
178	  return result;
179	};
