181	/**
182	 * Pure function to redact identifying info (URLs, emails, handles, phone numbers, and roster names)
183	 * from comments according to ADR 0001 and ADR 0009.
184	 */
185	export const redact = (text: string, roster: Roster): string => {
186	  if (!text) return "";
187	
188	  // 1,000-character limit counted after Unicode normalization
189	  const normalized = text.normalize("NFC");
190	  const bounded = normalized.length > 1000 ? normalized.slice(0, 1000) : normalized;
191	
192	  // 1. Redact URLs
193	  let result = bounded.replace(URL_PATTERN, "[link]");
194	
195	  // 2. Redact Email addresses
196	  result = result.replace(EMAIL_PATTERN, "[email]");
197	
198	  // 3. Redact @handles
199	  result = result.replace(HANDLE_PATTERN, "[handle]");
200	
201	  // 4. Redact Phone numbers (7+ digits with separators, keeping plain numbers)
202	  result = result.replace(PHONE_PATTERN, (match, p1: string) => {
203	    const digits = (p1.match(/\d/g) ?? []).length;
204	    const hasSeparators = /[-.\s()+]/.test(p1);
205	    if (digits >= 7 && hasSeparators) {
206	      return match.replace(p1, "[phone]");
207	    }
208	    return match;
209	  });
210	
211	  // 5. Redact roster names
212	  const candidates = extractCandidateNames(roster);
213	  result = redactNames(result, candidates);
214	
215	  return result;
216	};
