4	describe("redact", () => {
5	  const roster: Roster = [
6	    "Anna",
7	    "Mary Ann Lee",
8	    "will",
9	    "may",
10	    { name: "John Doe", email: "john.doe@example.com" },
11	    { firstName: "Ada", lastName: "Lovelace", email: "ada@example.com" },
12	  ];
13	
14	  it("redacts case and accents: anna, ANNA, Ánna", () => {
15	    expect(redact("Talked to anna yesterday.", roster)).toBe("Talked to [name] yesterday.");
16	    expect(redact("Talked to ANNA yesterday.", roster)).toBe("Talked to [name] yesterday.");
17	    expect(redact("Talked to Ánna yesterday.", roster)).toBe("Talked to [name] yesterday.");
18	  });
19	
20	  it("redacts possessives: Anna's, Anna’s", () => {
21	    expect(redact("That was Anna's presentation.", roster)).toBe("That was [name]'s presentation.");
22	    expect(redact("That was Anna’s presentation.", roster)).toBe("That was [name]’s presentation.");
23	  });
24	
25	  it("redacts multi-word names: Mary Ann Lee", () => {
26	    expect(redact("Mary Ann Lee led the meeting.", roster)).toBe("[name] led the meeting.");
27	    expect(redact("Mary Ann Lee's project was great.", roster)).toBe("[name]'s project was great.");
28	  });
29	
30	  it("redacts ordinary words that are roster names: will, may", () => {
31	    expect(redact("This will happen soon.", roster)).toBe("This [name] happen soon.");
32	    expect(redact("We may need more time.", roster)).toBe("We [name] need more time.");
33	  });
34	
35	  it("redacts an email address, 5 phone formats, an @handle, and a URL containing a name", () => {
36	    // 1. Email address
37	    expect(redact("Contact me at someone@domain.com for info.", roster)).toBe(
38	      "Contact me at [email] for info.",
39	    );
40	
41	    // 2. Five phone formats
42	    expect(redact("Call +1 (555) 234-5678 today.", roster)).toBe("Call [phone] today.");
43	    expect(redact("Call 555-234-5678 today.", roster)).toBe("Call [phone] today.");
44	    expect(redact("Call (555) 234-5678 today.", roster)).toBe("Call [phone] today.");
45	    expect(redact("Call 555.234.5678 today.", roster)).toBe("Call [phone] today.");
46	    expect(redact("Call +49 30 1234567 today.", roster)).toBe("Call [phone] today.");
47	
48	    // Plain numbers stay
49	    expect(redact("We served 1000000 customers in 2026 with 50000 items.", roster)).toBe(
50	      "We served 1000000 customers in 2026 with 50000 items.",
51	    );
52	
53	    // 3. @handle
54	    expect(redact("Ping @chrisdoc or @anna on chat.", roster)).toBe("Ping [handle] or [handle] on chat.");
55	
56	    // 4. URL containing a name
57	    expect(redact("See https://example.com/anna/profile for details.", roster)).toBe(
58	      "See [link] for details.",
59	    );
60	  });
61	
62	  it("redacts names glued to punctuation: (Anna), Anna,, Anna!", () => {
63	    expect(redact("Great idea (Anna)!", roster)).toBe("Great idea ([name])!");
64	    expect(redact("Thanks, Anna, for your help.", roster)).toBe("Thanks, [name], for your help.");
65	    expect(redact("Anna! What a surprise.", roster)).toBe("[name]! What a surprise.");
66	  });
67	
68	  it("keeps 'Ann' inside 'annual'", () => {
69	    expect(redact("Our annual planning is next week.", roster)).toBe("Our annual planning is next week.");
70	  });
71	
72	  it("extracts and redacts names from object roster items and email local parts", () => {
73	    expect(redact("Reviewed by John Doe.", roster)).toBe("Reviewed by [name].");
74	    expect(redact("Reviewed by John.", roster)).toBe("Reviewed by [name].");
75	    expect(redact("Sent by ada.", roster)).toBe("Sent by [name].");
76	  });
77	
78	  it("ignores names shorter than 2 characters", () => {
79	    const singleLetterRoster: Roster = ["A", "x", "Bob"];
80	    expect(redact("A quick test with Bob and x.", singleLetterRoster)).toBe(
81	      "A quick test with [name] and x.",
82	    );
83	  });
84	
85	  it("enforces 1,000-character limit after Unicode normalisation", () => {
86	    const longText = "a".repeat(1050) + " Anna";
87	    const result = redact(longText, roster);
88	    expect(result.length).toBeLessThanOrEqual(1000);
89	    expect(result).not.toContain("Anna");
90	  });
