111	    ];
112	
113	    // Seeded-style pseudo random generator
114	    let seed = 42;
115	    const rnd = () => {
116	      seed = (seed * 9301 + 49297) % 233280;
117	      return seed / 233280;
118	    };
119	
120	    for (let i = 0; i < 50; i++) {
121	      const sentenceLength = Math.floor(rnd() * 15) + 5;
122	      const sentenceWords: Array<string> = [];
123	
124	      for (let j = 0; j < sentenceLength; j++) {
125	        if (rnd() < 0.3) {
126	          // Insert a roster name with possible punctuation or possessive
127	          const name = names[Math.floor(rnd() * names.length)]!;
128	          const variant = rnd();
129	          if (variant < 0.25) sentenceWords.push(name.toLowerCase());
130	          else if (variant < 0.5) sentenceWords.push(name.toUpperCase());
131	          else if (variant < 0.75) sentenceWords.push(`${name}'s`);
132	          else sentenceWords.push(`(${name})`);
133	        } else {
134	          sentenceWords.push(words[Math.floor(rnd() * words.length)]!);
135	        }
136	      }
137	
138	      const sentence = sentenceWords.join(" ") + ".";
139	      const redacted = redact(sentence, testRoster);
140	
